export function completeReferenceFeatures(classId: string, features: ReferenceFeatureCard[]): ReferenceFeatureCard[] {
  const rules = baseRules[classId] ?? {}
  const completed = features.map((feature) => {
    const rule = rules[`${feature.level}:${feature.name}`]
    return rule ? { ...feature, mechanics: rule.mechanics, details: rule.details ?? [] } : feature
  })

  return [...completed, ...(missingBaseCards[classId] ?? [])].sort((a, b) => a.level - b.level)
}

export function completeSubclassFeatures(subclassId: string, features: ReferenceFeatureCard[]): ReferenceFeatureCard[] {
  const rules = subclassRules[subclassId] ?? {}
  return features.map((feature) => {
    const mechanics = rules[feature.level]
    return mechanics ? { ...feature, mechanics } : feature
  })
}

